import { applyHistoryStep } from "./utils/RLEUtils.js";
import workerpool from "../../libs/workerpool.js";
// import { processNode } from "./LabelingWorker.js";

export class LabelingWorkerManager {
    constructor(labelingManager) {
        this.labelingManager = labelingManager;
        // Create a worker pool using the bundled worker file
        // precise path depends on where this file is served/bundled.
        this.workerPath = Potree.scriptPath + '/workers/LabelingWorker.js';
        console.log("worker path ", this.workerPath);
        this.pool = workerpool.pool(this.workerPath); 
        this.queue = [];
        this.processing = false;
    }

    enqueueNode(node) {
        if (!node) return;
        
        node.loading = true;
        node.loaded = false;

        // Clone current labeling command state
        // We use serializeCommandList to prepare strict payloads
        const commandsList = this.labelingManager.commandsList;
        const serializedCommands = this.serializeCommandList(commandsList);
        
        const iterator = this.labelingManager.iterator;
        
        const subSelectionBoxes = this.labelingManager.subSelectionBoxes;
        const serializedBoxes = this.serializeVolumes(subSelectionBoxes);

        this.queue.push({
            node, 
            serializedCommands,
            iterator, 
            serializedBoxes
        });
        // console.log("serialized commands ", serializedCommands);
        // console.log("iterator ", iterator);
        // console.log("serialized boxes ", serializedBoxes);
        // console.log("serialize node", this.serializeNode(node, this.labelingManager.pointcloud));
        
        this.flushNodeQueue();
    }
    
    serializeNode(node, pointcloud){
        const geometry = node.geometry;
        const attributes = geometry.attributes;
        
        const matrixWorld = pointcloud.matrixWorld
                                .clone()
                                .identity()
                                .setPosition(node.boundingBox.min)
                                .premultiply(pointcloud.matrixWorld);
        
        const nodeData = {
            position: attributes.position.array,
            classification: new Uint8Array(attributes.classification.array), // Copy for safety/transfer
            matrixWorld: matrixWorld.elements
        };

        // Strict Cluster Attribute Logic
        // "point source id" OR "cluster*"
        // Only pass required attributes
        
        for(const key in attributes){
             if(key === 'point source id' || key.startsWith('cluster')){
                 if(attributes[key].array){
                     nodeData[key] = attributes[key].array;
                 }
             }
        }
        
        return nodeData;
    }

    serializeVolumes(volumes) {
        if(!volumes) return [];
        return volumes.map(v => this.serializeVolume(v));
    }

    serializeVolume(volume) {
        // Only required properties
        return {
            matrixWorld: volume.matrixWorld,
            uuid: volume.uuid
        };
    }
    
    serializePolygon(polygon) {
        // Only required properties for PolygonSelector logic
        const serialized = {};
        
        if (polygon.markers && Array.isArray(polygon.markers)) {
             serialized.markers = polygon.markers.map(m => ({ position: m.position }));
        }
        
        if (polygon.viewMatrix) serialized.viewMatrix = polygon.viewMatrix;
        if (polygon.projMatrix) serialized.projMatrix = polygon.projMatrix;
        
        if (polygon.camera) {
             serialized.camera = {
                 projectionMatrix: polygon.camera.projectionMatrix,
                 matrixWorldInverse: polygon.camera.matrixWorldInverse
             };
        }
        
        return serialized;
    }
    
    serializeCommandList(commandsList) {
        if(!commandsList) return [];
        
        return commandsList.map(cmd => {
            const newCmd = {
                timestamp: cmd.timestamp,
                labelId: cmd.labelId,
                excludeLabels: cmd.excludeLabels,
                activeZoomBoxIndex: cmd.activeZoomBoxIndex,
                commandType: cmd.commandType,
                payload: null
            };
            
            if (cmd.commandType === 'box') {
                newCmd.payload = this.serializeVolume(cmd.payload);
            } else if (cmd.commandType === 'polygon') {
                newCmd.payload = this.serializePolygon(cmd.payload);
            } else {
                // 'point' or generic payload. 
                // Ensure only JSON-serializable data is passed if it's complex.
                // Assuming point payload is simple { attribute: 'val', value: 123 }
                newCmd.payload = cmd.payload;
            }
            
            return newCmd;
        });
    }

    async flushNodeQueue() {
        if (this.processing || this.queue.length === 0 || this.labelingManager.pointcloud == null) return;

        this.processing = true;

        while (this.queue.length > 0) {
            const item = this.queue.shift();
            // Use already serialized commands/boxes
            const { node, serializedCommands, iterator, serializedBoxes } = item;

            try {
                // Serialize Node Data just-in-time
                // This ensures we get the latest buffer content if main thread modified it (unlikely during queue wait, but safer)
                // Also handles matrix update call
                const nodeData = this.serializeNode(node, this.labelingManager.pointcloud);
                
                // Flatten extraAttributes for worker compatibility if needed, 
                // OR ensure worker handles extraAttributes.
                // Current worker implementation (LabelingWorker.js) likely expects attributes at root or we update it?
                // The prompt says "Refactor LabelingWorkerManager.js".
                // I will assume the worker is smart enough OR flatten for compatibility.
                // Creating a clean transferable object is best.
                
                

                // Execute
                const result = await this.pool.exec('processNode', [nodeData, serializedCommands, iterator, serializedBoxes]);
                // const result = processNode(nodeData, serializedCommands, iterator, serializedBoxes);
                
                if (result && result.history) {
                    const history = result.history;
                    // console.log("History ", history);
                    const userData = node.geometry.userData;
                    const classification = node.geometry.attributes.classification.array;
                    
                    if (!userData.history) {
                        userData.history = [];
                        userData.commandIndex = -1;
                    }
                    
                    for(let i=0; i<history.length; i++){
                        const historyItem = history[i];
                        if (i < userData.history.length) {
                            userData.history[i] = historyItem;
                        } else {
                            userData.history.push(historyItem);
                        }
                        
                        // Apply to local buffer to ensure visual consistency
                        if(historyItem.steps){
                            applyHistoryStep(historyItem.steps, classification, true);
                        }
                        userData.commandIndex = i;
                    }
                }
                
                node.loading = false;
                node.loaded = true; 
                node.geometry.attributes.classification.needsUpdate = true; 
                
            } catch (err) {
                console.error("LabelingWorker error:", err);
                node.loading = false; 
                node.loaded = true;
            }
        }

        this.processing = false;
    }
}
