
import * as THREE from "../../libs/three.js/build/three.module.js";
import {BoxVolume, ZoomedInBoxVolume} from "../utils/Volume.js";
import {EventDispatcher} from "../EventDispatcher.js";
import {Utils} from "../utils.js";

export class VolumeLabelingTool extends EventDispatcher {
    constructor(viewer, volumeType, leaveBox = false) {
        super();
        this.viewer = viewer;
        this.volumeType = volumeType;
        this.leaveBox = leaveBox;
        this.renderer = viewer.renderer;
        this.scene = new THREE.Scene();
        this.scene.name = 'scene_volume_labeling';

        this.viewer.inputHandler.registerInteractiveScene(this.scene);

        this.onRemove = (e) => { this.scene.remove(e.volume); };
        this.onAdd = (e) => { this.scene.add(e.volume); };

        this.viewer.addEventListener("update", this.update.bind(this));
        this.viewer.addEventListener("render.pass.perspective_overlay", this.render.bind(this));
    }

    startInsertion(args={}) {
        let volume;
        if(this.volumeType == "boxVolume"){
            volume = new BoxVolume();
        }else if(this.volumeType == "zoomedInBoxVolume"){
            volume = new ZoomedInBoxVolume(this.viewer);
        }else{
            throw new Error("Invalid volume type");
        }
        volume.visible = false; 
        volume.material.visible = false; // Hide green highlight box, keeping only the frame
        volume.showVolumeLabel = false;
        

        this.scene.add(volume);

        const lineGeometry = new THREE.BufferGeometry();
        const lineMaterial = new THREE.LineBasicMaterial({ color: 0x00ff00, depthTest: false });
        const diagonalLine = new THREE.Line(lineGeometry, lineMaterial);
        diagonalLine.visible = false;
        this.scene.add(diagonalLine);

        // Red sphere for cursor/point visualization
        const sphereGeometry = new THREE.SphereGeometry(0.25, 32, 32);
        const sphereMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000, depthTest: false, depthWrite: false });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.visible = false;
        this.scene.add(sphere);

        let startPoint = null;
        let created = false;
        
        const cancel = { callback: null };

        const insertionCallback = (e) => {
            if (e.button === THREE.MOUSE.LEFT) {
                if (created) {
                    // Volume already created and selected. 
                    // Do nothing here, let InputHandler handle interactions (dragging handles).
                    // Or if we want to support "Click off to confirm", we'd need logic here.
                    // But user request implies "Right click disappears", "Selected for update".
                    // So we stay in this state until tool is cancelled/switched.
                    return;
                }

                const mouse = { x: e.offsetX, y: e.offsetY };
                if (!startPoint) {
                    // First click: Set start point
                    const I = Utils.getMousePointCloudIntersection(
                        mouse,
                        this.viewer.scene.getActiveCamera(),
                        this.viewer,
                        this.viewer.scene.pointclouds,
                        { pickClipped: true }
                    );

                    if (I) {
                        startPoint = I.location.clone();
                        volume.visible = true;
                        diagonalLine.visible = true;
                        
                        this.updateVolume(volume, diagonalLine, startPoint, startPoint);
                    }
                } else {
                    // Second click: Confirm volume
                     const I = Utils.getMousePointCloudIntersection(
                        mouse,
                        this.viewer.scene.getActiveCamera(),
                        this.viewer,
                        this.viewer.scene.pointclouds,
                        { pickClipped: true }
                    );
                    
                    if (I) {
                        this.updateVolume(volume, diagonalLine, startPoint, I.location);
                        
                        created = true;
                        
                        if (this.viewer.labelingManager && this.viewer.labelingManager.handleVolume) {
                            this.viewer.labelingManager.handleVolume(volume, this.volumeType);
                        }
                        
                        this.scene.remove(diagonalLine);
                        this.scene.remove(sphere); 
                        
                        // Select the volume for update
                        this.viewer.inputHandler.startDragging(volume);
                        
                        // NOTE: We do NOT call cancel.callback() here. We keep the tool active.
                        this.viewer.inputHandler.enabled = true;
                    }
                }
            } else if (e.button === THREE.MOUSE.RIGHT) {
                cancel.callback(e);
            }
        };

        const mouseMoveCallback = (e) => {
             if (created) return; // Stop rubber-banding if created

             const mouse = { x: e.offsetX, y: e.offsetY };
             const I = Utils.getMousePointCloudIntersection(
                mouse,
                this.viewer.scene.getActiveCamera(),
                this.viewer,
                this.viewer.scene.pointclouds,
                { pickClipped: true }
             );

            if (I) {
                sphere.visible = true;
                sphere.position.copy(I.location);
                
                if (startPoint) {
                    this.updateVolume(volume, diagonalLine, startPoint, I.location);
                }
            } else {
                sphere.visible = false;
            }
        };

        cancel.callback = (e) => {
            // Unconditionally remove all tool artifacts from local scene
            if(!this.leaveBox || !created){
                this.scene.remove(volume);
                this.scene.remove(diagonalLine);
                this.scene.remove(sphere);

                // Also ensure it is removed from the global viewer scene if it was added
                if (this.viewer.scene.volumes.includes(volume)) {
                    this.viewer.scene.removeVolume(volume);
                }
            }
            
            this.viewer.renderer.domElement.removeEventListener("mouseup", insertionCallback, false);
            this.viewer.renderer.domElement.removeEventListener("mousemove", mouseMoveCallback, false);
            this.viewer.removeEventListener("cancel_insertions", cancel.callback);
            this.viewer.inputHandler.enabled = true;

            if(args.onFinish){
                args.onFinish();
            }
        };

        this.viewer.addEventListener("cancel_insertions", cancel.callback);
        this.viewer.renderer.domElement.addEventListener("mousemove", mouseMoveCallback, false);
        this.viewer.renderer.domElement.addEventListener("mouseup", insertionCallback, false);
        this.viewer.inputHandler.enabled = false;

        return volume;
    }

    updateVolume(volume, line, start, end) {
        const positions = new Float32Array([
            start.x, start.y, start.z,
            end.x, end.y, end.z
        ]);
        line.geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        
        const mid = new THREE.Vector3().addVectors(start, end).multiplyScalar(0.5);
        volume.position.copy(mid);

        const size = new THREE.Vector3().subVectors(end, start);
        volume.scale.set(Math.abs(size.x), Math.abs(size.y), Math.abs(size.z));
        
        volume.scale.x = Math.max(volume.scale.x, 0.001);
        volume.scale.y = Math.max(volume.scale.y, 0.001);
        volume.scale.z = Math.max(volume.scale.z, 0.001);

        volume.update();
    }

    update() {
        const camera = this.viewer.scene.getActiveCamera();
        const domElement = this.renderer.domElement;
        const renderAreaSize = this.renderer.getSize(new THREE.Vector2());
        const clientWidth = renderAreaSize.width;
        const clientHeight = renderAreaSize.height;

        this.scene.children.forEach(child => {
            if (child instanceof THREE.Mesh && child.geometry instanceof THREE.SphereGeometry) {
                const sphere = child;
                const distance = camera.position.distanceTo(sphere.getWorldPosition(new THREE.Vector3()));
                const pr = Utils.projectedRadius(1, camera, distance, clientWidth, clientHeight);
                const scale = (15 / pr);
                sphere.scale.set(scale, scale, scale);
            }
        });
    }

    render() {
        this.viewer.renderer.render(this.scene, this.viewer.scene.getActiveCamera());
    }
}
