import { convertIndicesToRanges, applyHistoryStep } from "./utils/RLEUtils.js";
import { ClusterSelector } from "./actions/ClusterSelector.js";
import { PolygonSelector } from "./actions/PolygonSelector.js";
import { VolumeSelector } from "./actions/VolumeSelector.js";

export class LabelingEngine {
    
    static update(viewer, commandsList, iterator, inProcessing, zoomedInBoxes) {
        if (!viewer || !viewer.scene || !viewer.scene.pointclouds) return;
        
        // 1. Get Visible Nodes
        // Assuming viewer.scene.pointclouds is array, we might iterate all of them.
        for (const pointcloud of viewer.scene.pointclouds) {
             if(!pointcloud.visibleNodes) continue;
             
             // Iterate visible nodes
             for (const node of pointcloud.visibleNodes) {
                 this.updateNode(node, commandsList, iterator, inProcessing, zoomedInBoxes, pointcloud);
             }
        }
    }

    static updateNode(node, commandsList, iterator, inProcessing, zoomedInBoxes, pointcloud) {
        if (!node.geometryNode || !node.geometryNode.geometry || !node.sceneNode) return;

        const geometry = node.geometryNode.geometry;
        const userData = geometry.userData;
        
        // Initialize history if needed
        if (!userData.history) {
            userData.history = [];
            userData.commandIndex = -1; // Last applied command index
        }

        // Logic similar to labeling.js updateNodeLabels
        // We sync userData.commandIndex with commandsList.length
        
        const targetCommandCount = iterator;
        // 1. Revert Backwards if needed (Undo)
        // If we are ahead of the target (e.g. user undid commands), revert
        while (userData.commandIndex >= targetCommandCount - (inProcessing ? 1 : 0)) {
             const historyStep = userData.history[userData.commandIndex];
             // Apply Backward (Revert)
             applyHistoryStep(historyStep.steps, geometry.attributes.classification.array, false);
             userData.commandIndex--;
             geometry.attributes.classification.needsUpdate = true;
        }

        // 2. Apply Forwards (New Commands of Redo)
        // Iterate from current index + 1 up to target
        for (let i = userData.commandIndex + 1; i < targetCommandCount; i++) {
            const command = commandsList[i];
            
            // Check if history already exists for this command timestamp
            // (Cache hit for Undo/Redo or Redraw)
            let historyStep = userData.history[i];
            
            if (!historyStep || historyStep.timestamp !== command.timestamp || inProcessing) {
                // Not found or mismatch -> Compute locally
                const steps = this.computeCommandImpact(node, command, zoomedInBoxes, pointcloud);
                
                historyStep = {
                    steps: steps,
                    timestamp: command.timestamp
                };
                
                // Store/Overwrite history at this index
                if (i < userData.history.length) {
                    userData.history[i] = historyStep;
                } else {
                    userData.history.push(historyStep);
                }
                // Truncate any future history if we diverged (standard history behavior)
                // Actually, if we are at i, and we computed new history, valid history ends at i.
                // But simplified: just assigning is fine if we assume linear append for new commands.
            }

            // Apply Forward
            applyHistoryStep(historyStep.steps, geometry.attributes.classification.array, true);
            
            userData.commandIndex = i;
            geometry.attributes.classification.needsUpdate = true;
        }
    }

    static computeCommandImpact(node, command, zoomedInBoxes, pointcloud) {
        // Extract Node Data
        const geometry = node.geometryNode.geometry;
        const inputData = {
            position: geometry.attributes.position.array,
            classification: geometry.attributes.classification.array,
            matrixWorld: node.sceneNode.matrixWorld.elements
        };
        
        if (command.commandType === 'point' && command.payload.attribute) {
             // Look for the attribute in geometry
             // Note: buffer attributes might be lower case
             const attrName = command.payload.attribute;
             // Try to find it
             const attr = geometry.attributes[attrName] || 
                          geometry.attributes[attrName.toLowerCase()] ||
                          geometry.attributes[attrName.replace(/ /g, '')]; // e.g. "point source id" -> "pointsourceid"
             
             if (attr) {
                 inputData[attrName] = attr.array;
             }
        }
        
        
        // Active Zoom Box
        let activeZoomBox = null;
        if (command.activeZoomBoxIndex !== -1 && zoomedInBoxes && command.activeZoomBoxIndex < zoomedInBoxes.length) {
            activeZoomBox = zoomedInBoxes[command.activeZoomBoxIndex];
        }


        // Select Indices based on command type
        let affectedIndices = [];
        
        switch (command.commandType) {
            case 'point':
                affectedIndices = ClusterSelector.select(inputData, command.payload, activeZoomBox);
                break;
            case 'polygon':
                 affectedIndices = PolygonSelector.select(inputData, command.payload, activeZoomBox);
                 break;
            case 'box':
                 affectedIndices = VolumeSelector.select(inputData, command.payload, activeZoomBox);
                 break;
            default:
                console.warn("Unknown command type:", command.commandType);
        }

        // Prepare History Steps (RLE)
        // Filter exclusions if needed
        if (command.excludeLabels && command.excludeLabels.length > 0) {
            affectedIndices = affectedIndices.filter(idx => {
               const currentLabel = inputData.classification[idx];
               // Check if current label is in exclusion list
               // command.excludeLabels is array of label IDs.
               // We might need to map them or assume direct match?
               // command.excludeLabels are "Ids" (e.g. 0, 1) which usually match stored values.
               return !command.excludeLabels.includes(currentLabel);
            });
        }
        
        // Convert to Ranges
        const targetLabel = command.labelId; // The new label to apply
        
        const ranges = convertIndicesToRanges(affectedIndices, inputData.classification, targetLabel);
        
        return ranges;
    }
}
