/**
 * Converts a list of affected point indices into Run-Length Encoded ranges.
 * Used to store history steps efficiently.
 * 
 * @param {number[]} indices - Sorted list of modified point indices
 * @param {Float32Array} currentLabels - The current label buffer (to get old values)
 * @param {number} targetLabel - The new label value being applied
 * @returns {Object[]} Array of history blocks { ranges: [start, end, ...], valueForward, valueBackward }
 */
export function convertIndicesToRanges(indices, currentLabels, targetLabel) {
    if (!indices || !indices.length) return [];
    
    const result = [];
    let start = indices[0];
    let ranges = [];
    
    // Initial block
    let currentBlock = {
        ranges: ranges,
        valueForward: targetLabel,
        valueBackward: currentLabels[start]
    };
    result.push(currentBlock);

    for (let i = 0; i < indices.length; i++) {
        const idx = indices[i];
        const nextIdx = indices[i+1];
        const isLast = (i === indices.length - 1);
        
        const labelCurrent = currentLabels[idx]; // The "old" value (valueBackward)
        const labelNext = (!isLast) ? currentLabels[nextIdx] : null;
        
        // We break the block if:
        // 1. The indices are not contiguous (gap in selection)
        // 2. The "old" label value changes (we need to group by old value to support undo)
        
        const gapDetected = (!isLast && nextIdx !== idx + 1);
        const labelChanged = (!isLast && labelCurrent !== labelNext);
        
        if (gapDetected || isLast || labelChanged) {
            // Close the current range
            ranges.push(start, idx + 1); // [start, end)
            
            // If not last, prepare for next
            if (!isLast) {
                start = nextIdx;
                
                if (labelChanged) {
                    // Start a new block entirely because the "backward" value changed
                    ranges = [];
                    currentBlock = {
                        ranges: ranges,
                        valueForward: targetLabel,
                        valueBackward: labelNext
                    };
                    result.push(currentBlock);
                }
            }
        }
    }
    return result;
}

/**
 * Fills a buffer with a value for specific ranges.
 * @param {number[]} ranges - Array of [start, end, start, end...]
 * @param {Float32Array} buffer - Target buffer to modify
 * @param {number} value - Value to set
 */
export function fillBufferFromRanges(ranges, buffer, value) {
    for (let i = 0; i < ranges.length; i += 2) {
        const start = ranges[i];
        const end = ranges[i+1];
        for (let j = start; j < end; j++) {
            buffer[j] = value;
        }
    }
}

/**
 * Applies a history step (or multiple steps) to a buffer.
 * @param {Object[]} steps - Array of { ranges, valueForward, valueBackward }
 * @param {Float32Array} buffer - Target buffer
 * @param {boolean} useForward - True to apply 'valueForward' (Redo/Apply), False for 'valueBackward' (Undo)
 */
export function applyHistoryStep(steps, buffer, useForward) {
    if(!steps) return;
    for (const step of steps) {
        const value = useForward ? step.valueForward : step.valueBackward;
        fillBufferFromRanges(step.ranges, buffer, value);
    }
}
