import { isPointInBounds, isPointInProjectedPolygon, setVectorFromBuffer, multiplyMatrices } from "../utils/GeometryUtils.js";
import * as THREE from "../../../libs/three.js/build/three.module.js";

export class PolygonSelector {
    /**
     * Finds indices of points that are inside the projected polygon and active zoom box.
     * 
     * @param {Object} nodeData - extracted data { position, labels, matrixWorld }
     * @param {Object} payload - command payload { polygonVertices, cameraProjectionMatrixWorldInverted, ... }
     * @param {Object} activeZoomBox - The active zoom box object (optional)
     * @returns {number[]} Array of point indices
     */
    static select(nodeData, payload, activeZoomBox) {
        const { position, matrixWorld } = nodeData;
        
        // Payload structure usually comes from PolygonLabelingTool or manual creation:
        // payload: { polygonVertices: [...], cameraProjectionMatrixWorldInverted: [...] }
        // The 'polygonVertices' are 2D or 3D points? Usually 3D points on the near plane or similar?
        // Reference labeling.js says: "polyVertices = selector.polygonVertices.map(v => v.position).filter..."
        // It uses "polyProjection = multiplyMatrices(selector.cameraProjectionMatrixWorldInverted, matrixWorld)"
        // This suggests: PointLocal -> PointWorld -> Projected (Screen/NDC) -> Check against 2D Selection Polygon
        
        const { polygon: polygonVertices, cameraMatrix } = this.parsePayload(payload);
        
        if(!polygonVertices || !cameraMatrix) return [];

        // 1. Prepare Polygon Projection Matrix: NodeLocal -> Screen/NDC
        // Matrix = CameraProjectionMatrixWorldInverse * NodeWorldMatrix ?? 
        // Wait, "cameraProjectionMatrixWorldInverted" in the reference seems misnamed or I need to check its content.
        // Usually: ModelViewProjection = Projection * View * Model
        // "cameraProjectionMatrixWorldInverted" might be "ViewProjectionMatrix"?
        // Let's assume the payload provides the matrix needed to go from World -> Screen/NDC.
        
        // In LabelingManager/PolygonLabelingTool, we should ensure we save the ViewProjection matrix.
        // Let's assume payload.cameraMatrix IS the ViewProjection matrix (or similar).
        
        const nodeMatrix = new THREE.Matrix4().fromArray(matrixWorld);
        const viewProjMatrix = new THREE.Matrix4().fromArray(cameraMatrix);
        
        // The reference multiplies: selector.cameraProjectionMatrixWorldInverted * matrixWorld
        // So M = ViewProj * Model
        const polyProjection = viewProjMatrix.clone().multiply(nodeMatrix).elements;


        // 2. Prepare Zoom Box Matrix (World -> Local)
        let boxInverted = null;
        if (activeZoomBox) {
            const boxInverse = new THREE.Matrix4().copy(activeZoomBox.matrixWorld).invert();
            const combined = boxInverse.multiply(nodeMatrix); // Local Node -> Local Box
            boxInverted = combined.elements;
        }

        const tempVec = { x: 0, y: 0, z: 0 };
        const numPoints = position.length / 3;
        const affectedIndices = [];

        for (let i = 0; i < numPoints; i++) {
            setVectorFromBuffer(tempVec, position, i * 3);
            
            // Check Zoom Box
            if (isPointInBounds(boxInverted, tempVec)) {
                
                // Check Polygon (Projected)
                // polyProjection takes Local Node -> NDC
                if (isPointInProjectedPolygon(tempVec.x, tempVec.y, tempVec.z, polyProjection, polygonVertices)) {
                    affectedIndices.push(i);
                }
            }
        }

        return affectedIndices;
    }
    
    static parsePayload(payload){
        // Strict handling of PolygonClipVolume structure as per user feedback
        // The payload IS the PolygonClipVolume object (or serialized version of it)
        
        let polygonVertices = null;
        let cameraMatrix = null;

        // Note: PolygonClipVolume stores markers in 'this.markers' and matrices in 'this.viewMatrix'/'this.projMatrix'
        if (payload.markers && Array.isArray(payload.markers)) {
             // Extract vertices from markers.
             // Markers are THREE.Mesh objects, or objects with .position property (NDC)
             polygonVertices = payload.markers.map(m => m.position);
             
             // Extract Matrices
             // We need View * Projection (or rather Projection * View)
             let view = payload.viewMatrix;
             let proj = payload.projMatrix;

             // Handle potential types (Array elements vs Matrix4 object)
             if (view && proj) {
                 const mProj = new THREE.Matrix4();
                 if(proj.elements) mProj.copy(proj);
                 else if(Array.isArray(proj)) mProj.fromArray(proj);
                 else if(proj.length) mProj.fromArray(proj); // Handle raw array
                 
                 const mView = new THREE.Matrix4();
                 if(view.elements) mView.copy(view);
                 else if(Array.isArray(view)) mView.fromArray(view);
                 else if(view.length) mView.fromArray(view);

                 // VP = P * V
                 cameraMatrix = mProj.multiply(mView).elements;
             } 
             
             // Fallback: if view/proj missing but camera exists (e.g. freshly created)
             if (!cameraMatrix && payload.camera) {
                 const camera = payload.camera;
                 const mProj = new THREE.Matrix4();
                 if(camera.projectionMatrix) mProj.copy(camera.projectionMatrix);
                 
                 const mView = new THREE.Matrix4();
                 // PolygonClipVolume stores inverse world matrix as view matrix logic
                 if(camera.matrixWorldInverse) mView.copy(camera.matrixWorldInverse);
                 
                 cameraMatrix = mProj.multiply(mView).elements;
             }
        }

        // Return empty/null if extraction failed, caller handles empty array
        return {
            polygon: polygonVertices,
            cameraMatrix: cameraMatrix 
        };
    }
}
