import { isPointInBounds, isPointInUnitCube, setVectorFromBuffer, multiplyMatrices } from "../utils/GeometryUtils.js";
import * as THREE from "../../../libs/three.js/build/three.module.js";

export class VolumeSelector {
    /**
     * Finds indices of points that are inside the selection volume/box and active zoom box.
     * 
     * @param {Object} nodeData - extracted data { position, matrixWorld }
     * @param {Object} payload - command payload { boxVolume } (The volume object itself or its properties)
     * @param {Object} activeZoomBox - The active zoom box object (optional)
     * @returns {number[]} Array of point indices
     */
    static select(nodeData, payload, activeZoomBox) {
        const { position, matrixWorld } = nodeData;
        
        // Payload is usually the Volume object or sufficient data to reconstruct it.
        // We need the Inverse World Matrix of the SELECTION BOX.
        // to transform PointWorld -> BoxLocal. Then check unit cube.
        
        // Let's assume payload IS the volume object or contains its matrixWorld.
        // Or payload contains 'matrixWorld' array.
        const selectionBoxMatrixWorld = payload.matrixWorld ? 
            (payload.matrixWorld.elements || payload.matrixWorld) : null;
            
        if (!selectionBoxMatrixWorld) {
            console.warn("VolumeSelector: No matrixWorld found in payload");
            return [];
        }

        // 1. Prepare Selection Box Matrix (NodeLocal -> SelectionBoxLocal)
        // Transform: PointLocal -> PointWorld -> PointSelectionBoxLocal
        // M = InvSelectionBoxWorld * NodeWorld
        
        const selBoxInverse = new THREE.Matrix4().fromArray(selectionBoxMatrixWorld).invert();
        const nodeMatrix = new THREE.Matrix4().fromArray(matrixWorld);
        const nodeToSelBox = selBoxInverse.clone().multiply(nodeMatrix).elements;


        // 2. Prepare Zoom Box Matrix (NodeLocal -> ZoomBoxLocal)
        let boxInverted = null;
        if (activeZoomBox) {
            const zoomBoxInverse = new THREE.Matrix4().copy(activeZoomBox.matrixWorld).invert();
            const combined = zoomBoxInverse.multiply(nodeMatrix); // Local Node -> Local ZoomBox
            boxInverted = combined.elements;
        }

        const tempVec = { x: 0, y: 0, z: 0 };
        const numPoints = position.length / 3;
        const affectedIndices = [];

        for (let i = 0; i < numPoints; i++) {
            setVectorFromBuffer(tempVec, position, i * 3);
            
            // Check Zoom Box First (Clipping)
            if (isPointInBounds(boxInverted, tempVec)) {
                
                // Check Selection Box
                // Check if point in nodeToSelBox space is in unit cube
                if (isPointInUnitCube(nodeToSelBox, tempVec)) {
                    affectedIndices.push(i);
                }
            }
        }

        return affectedIndices;
    }
}
