

export class Topbar {
    constructor(viewer) {
        this.viewer = viewer;
        this.labelingManager = viewer.labelingManager; // Use LabelingManager like Sidebar does

        this.dom = $("#topbar_root"); 
    }

    createToolIcon(icon, title, callback) {
        let element = $(`
            <img src="${icon}"
                style="width: 28px; height: 28px; margin: 0 4px; cursor: pointer;"
                class="button-icon"
                data-i18n="${title}" />
        `);

        element.click(callback);
        return element;
    }

    initLabelingDropdown() {
        let elContainer = $(
            `<div style="display: flex; align-items: center; gap: 6px;"></div>`
        );
        let label = $(`<span style="font-weight: bold;">Label For:</span>`);
        let dropdown = $(
            `<select id="labelingForDropdown" style="padding: 2px 6px; border-radius: 4px;"></select>`
        );

        // ✅ Add "None" option
        dropdown.append(`<option value="">None</option>`);

        // Populate dropdown with classifications
        for (let classID in this.viewer.classifications) {
            let name = this.viewer.classifications[classID].name;
            dropdown.append(`<option value="${classID}">${name}</option>`);
        }

        // Handle change
        dropdown.on("change", (e) => {
            let value = e.target.value;
            // setLabelingFor is the method used in Sidebar.js (line 271)
            this.labelingManager.setLabelingFor(value === "" ? null : value);
        });

        elContainer.append(label);
        elContainer.append(dropdown);
        this.dom.append(elContainer);

        // Set default if already selected
        // Sidebar uses updateLabelingDisplay to read from manager.
        // We can just read directly or listen to event if we want to be fancy.
        let current = this.labelingManager.getLabelingFor();
        if (current) {
            dropdown.val(current);
        } else {
            dropdown.val("");
        }
    }

    initLabelingTools() {
        let elToolbar = $(
            `<div id="topbarTools" style="display: flex; align-items: center; gap: 6px; margin-left: 16px;"></div>`
        );

        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/segment_labeling.svg",
                "[title]tt.label",
                () => this.labelingManager.triggerSegmentLabeling()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/polygon_label.svg",
                "[title]tt.clip_polygon",
                () => this.labelingManager.triggerPolygonLabeling()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/volume_label.svg",
                "[title]tt.clip_volume",
                () => this.labelingManager.triggerVolumeLabeling()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/bounding_box.svg",
                "[title]tt.clip_volume",
                () => this.labelingManager.triggerZoomedInCreation()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/select_bbox.svg",
                "[title]tt.zoom_toggle",
                () => this.labelingManager.toggleZoom()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/see_labeled.svg",
                "[title]tt.show_labeled",
                () => this.labelingManager.toggleShowLabeled()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/previous.svg",
                "[title]tt.prev",
                () => this.labelingManager.prevZoomBox()
            )
        );
        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/next.svg",
                "[title]tt.next",
                () => this.labelingManager.nextZoomBox()
            )
        );

        elToolbar.append(
            this.createToolIcon(
                Potree.resourcePath + "/icons/img.svg",
                "[title]tt.qa",
                () => this.viewer.toggleRotation()
            )
        );

        this.dom.append(elToolbar);
    }

    init() {
        this.initLabelingDropdown();
        this.initLabelingTools();
    }
}
