import {SegmentLabelingTool} from "./SegmentLabelingTool.js";
import {PolygonLabelingTool} from "./PolygonLabelingTool.js";
import {VolumeLabelingTool} from "./VolumeLabelingTool.js";
import * as THREE from "../../libs/three.js/build/three.module.js";
import { LabelingEngine } from "./LabelingEngine.js";
import { LabelingWorkerManager } from "./LabelingWorkerManager.js";

export class LabelingManager{
    constructor(viewer){
        this.viewer = viewer;
        this.classificationLocked = Object.fromEntries(
            Object.keys(this.viewer.classifications).map((key) => [
                key,
                !this.viewer.classifications[key].visible,
            ])
        );
        this.labelingFor = null;
        this.segmentLabelingTool = new SegmentLabelingTool(viewer);
        this.polygonLabelingTool = new PolygonLabelingTool(viewer);
        this.volumeLabelingTool = new VolumeLabelingTool(viewer, 'boxVolume', false);
        this.zoomedInVolumeLabelingTool = new VolumeLabelingTool(viewer, 'zoomedInBoxVolume', true);
        this.isLocked = false;
        this.iterator = 0;
        this.inProcessing = false;
        
        // Stage 1: Storage and State
        this.commandsList = [];
        this.zoomedInBoxes = [];
        this.subSelectionBoxes = [];
        this.currentZoomBoxIndex = -1;
        this.isZoomMode = false;
        
        this.labelingAttribute = 'point source id'; 

        this.workerManager = new LabelingWorkerManager(this);
        this.pointcloud = null;

        this.showLabeledOnly = false;
    }

    onPolygonFinish() {
        if(!this.commandsList[this.commandsList.length - 1].payload.initialized){
            this.commandsList.pop();
            this.iterator--;
        }
        this.update(); // HACK force update because here right click updates polygon too
        this.isLocked = false;
        this.inProcessing = false;
    }

    triggerSegmentLabeling() {
        if(this.isLocked) return;
        console.log("triggerSegmentLabeling called");
        this.isLocked = true;
        this.segmentLabelingTool.startInsertion({
            onFinish: () => { this.isLocked = false; }
        });
    }
    
    triggerPolygonLabeling() {
        if(this.isLocked || !this.labelingFor) return;
        console.log("triggerPolygonLabeling called");
        this.isLocked = true;
        this.polygonLabelingTool.startInsertion({
             type: 'polygon',
             onFinish: this.onPolygonFinish.bind(this)
        });
    }

    triggerVolumeLabeling() {
        if(this.isLocked || !this.labelingFor) return;
        console.log("triggerVolumeLabeling called");
        this.isLocked = true;
        this.volumeLabelingTool.startInsertion({
            type: 'box', 
            name: 'Labeling Volume',
            onFinish: () => { 
                this.isLocked = false;
                this.inProcessing = false;
            }
        });
    }

    triggerZoomedInCreation() {
        if(this.isLocked) return;
        console.log("triggerZoomedInCreation called");
        this.isLocked = true;
        this.zoomedInVolumeLabelingTool.startInsertion({
             type: 'box', 
             name: 'Zoomed In Volume',
             onFinish: () => { 
                this.isLocked = false;
            }
        });
    }

    handleSegmentClicks(point) {
        if(this.labelingAttribute in point && !this.getLabelingLock(point["classification"][0])){
            this.addCommand({ type: 'point', payload: {
                attribute: this.labelingAttribute,
                value: point[this.labelingAttribute][0]
            } });
            this.iterator++;
        }
    }

    handlePolygon(polygon) {
        console.log("handlePolygon called", polygon);
        this.addCommand({ type: 'polygon', payload: polygon });
        this.iterator++;
        this.inProcessing = true;
    }

    handleVolume(volume, volumeType) {
        console.log("handleVolume called", volume);
        if(volumeType == "zoomedInBoxVolume"){
            this.handleZoomedInCreation(volume);
        }else if(volumeType == "boxVolume"){
            this.handleLabeledVolumeCreation(volume);
        }
    }

    handleLabeledVolumeCreation(volume){
        console.log("handleLabeledVolumeCreation called");
        this.addCommand({ type: 'box', payload: volume });
        this.iterator++;
        this.inProcessing = true;
    }

    handleZoomedInCreation(volume){
        console.log("handleZoomedInCreation called", volume);
        this.isLocked = false;
        this.zoomedInBoxes.push(volume);
        this.selectZoomBox(volume.uuid);
    }

    addCommand(toolData) {
        if (this.labelingFor === null) {
            console.warn("Labeling skipped: No label selected (labelingFor is null)");
            return; 
        }
        if(this.isZoomMode){
            this.subSelectionBoxes.push(this.getActiveZoomBox().clone());
        }

        const command = {
            timestamp: Date.now(),
            labelId: this.labelingFor,
            excludeLabels: this.getLabelsToExclude(),
            activeZoomBoxIndex: this.isZoomMode ? this.subSelectionBoxes.length - 1 : -1,
            commandType: toolData.type,
            payload: toolData.payload
        };

        console.log("Adding Command:", command);
        this.commandsList = this.commandsList.slice(0, this.iterator);
        this.commandsList.push(command);
    }

    selectZoomBox(uuid){
        console.log("selectZoomBox called", uuid);
        const index = this.zoomedInBoxes.findIndex(b => b.uuid === uuid);
        if (index !== -1) {
            this.currentZoomBoxIndex = index;
        }
    }

    deSelectZoomBox(uuid){
        console.log("deSelectZoomBox called", uuid);
        if(!this.isZoomMode){
        this.currentZoomBoxIndex = -1;
        }
    }

    zoomToBox(){
		const object = this.getActiveZoomBox();
		let box = object.boundingBox.clone().applyMatrix4(object.matrixWorld);
		if(box.getSize(new THREE.Vector3()).length() > 0){
			let node = new THREE.Object3D();
			node.boundingBox = box;
			this.viewer.zoomTo(node, 1, 500);
		}
	}

    toggleZoom() {
        console.log("toggleZoom called");
        
        if (!this.isZoomMode) {
             if(this.currentZoomBoxIndex !== -1 && this.zoomedInBoxes.length > 0) {
                 this.isZoomMode = true;
                 this.zoomToBox();
                 console.log("Zoom Mode Enabled");
             }
        } else {
            this.isZoomMode = false;
            this.currentZoomBoxIndex = -1;
            console.log("Zoom Mode Disabled");
        }
    }

    prevZoomBox() {
        if (!this.isZoomMode || this.zoomedInBoxes.length === 0) return;

        this.currentZoomBoxIndex = (this.currentZoomBoxIndex - 1 + this.zoomedInBoxes.length) % this.zoomedInBoxes.length;
        this.zoomToBox();
    }

    nextZoomBox() {
        if (!this.isZoomMode || this.zoomedInBoxes.length === 0) return;
        
        this.currentZoomBoxIndex = (this.currentZoomBoxIndex + 1) % this.zoomedInBoxes.length;
        this.zoomToBox();
    }

    setLabelingFor(code) {
        console.log(`setLabelingFor called with code: ${code}`);
        this.labelingFor = code;
    }

    getLabelingFor() {
        return this.labelingFor;
    }

    setLabelingLock(code, isLocked) {
        console.log(`setLabelingLock called with code: ${code}, isLocked: ${isLocked}`);
        this.classificationLocked[code] = isLocked;
    }

    updateClassificationLocked() {
        this.classificationLocked = Object.fromEntries(
            Object.keys(this.viewer.classifications).map((key) => [
                key,
                !this.viewer.classifications[key].visible,
            ])
        );
        console.log(this.classificationLocked);
    }
    
    getLabelingLock(code) {
        if(code in this.classificationLocked){
            return this.classificationLocked[code];
        }
        return this.classificationLocked["DEFAULT"];
    }

    getLabelsToExclude(){
        const excludeLabels = [];
        for (const [key, locked] of Object.entries(this.classificationLocked)) {
            if (locked) {
                excludeLabels.push(parseInt(key));
            }
        }
        return excludeLabels;
    }

    toggleShowLabeled() {
        this.showLabeledOnly = !this.showLabeledOnly;
        console.log("toggleShowLabeled called ", this.showLabeledOnly);
    }

    getShowLabeled(){
        return this.showLabeledOnly;
    }

    getActiveZoomBox() {
        if (this.isZoomMode && this.currentZoomBoxIndex !== -1 && this.currentZoomBoxIndex < this.zoomedInBoxes.length) {
            return this.zoomedInBoxes[this.currentZoomBoxIndex];
        }
        return null;
    }

    update() {
        LabelingEngine.update(this.viewer, this.commandsList,this.iterator,this.inProcessing, this.subSelectionBoxes);
    }

    undo(){
        console.log("undo called");
        if(this.iterator > 0){
            this.iterator--;
        }
    }
    redo(){
        console.log("redo called");
        if(this.iterator < this.commandsList.length){
            this.iterator++;
        }
    }

    setLabelingData(data) {
        this.zoomedInBoxes = data.zoomInBoxes;
        this.subSelectionBoxes = data.subSelectionBoxes || []; // Handle case where property might be missing in older files
        this.commandsList = data.commandsList;
        this.iterator = data.iterator;
        console.log("setLabelingData called", data);
        
        if(this.zoomedInBoxes.length > 0){
            for(let volume of this.zoomedInBoxes){
				this.viewer.scene.scene.add(volume);
			}
            this.currentZoomBoxIndex = -1; 
        }
    }
    
    enqueueNode(node) {
        this.workerManager.enqueueNode(node);
    }
}