import * as THREE from "../../../libs/three.js/build/three.module.js";

/**
 * Multiplies two 4x4 matrices (provided as 16-element arrays)
 * @param {number[]} a - First matrix elements
 * @param {number[]} b - Second matrix elements
 * @returns {number[]} Resulting matrix elements
 */
export function multiplyMatrices(a, b) {
    const m1 = new THREE.Matrix4().fromArray(a);
    const m2 = new THREE.Matrix4().fromArray(b);
    return m1.multiply(m2).elements;
}

/**
 * Checks if a point (projected by projectionMatrix) is within a 2D polygon.
 * @param {number} x - Point X
 * @param {number} y - Point Y
 * @param {number} z - Point Z
 * @param {number[]} projectionMatrix - 4x4 Projection Matrix elements
 * @param {Object[]} polygonVertices - Array of {x, y, z} objects (z is ignored for 2D check)
 * @returns {boolean}
 */
export function isPointInProjectedPolygon(x, y, z, projectionMatrix, polygonVertices) {
    // Logic adapted to match user provided GLSL implementation exactly
    
    // 1. Calculate Clip Space (pointNDC in GLSL snippet, but before divide)
    // M * [x, y, z, 1]
    const clip_x = projectionMatrix[0] * x + projectionMatrix[4] * y + projectionMatrix[8] * z + projectionMatrix[12];
    const clip_y = projectionMatrix[1] * x + projectionMatrix[5] * y + projectionMatrix[9] * z + projectionMatrix[13];
    const clip_z = projectionMatrix[2] * x + projectionMatrix[6] * y + projectionMatrix[10] * z + projectionMatrix[14];
    const clip_w = projectionMatrix[3] * x + projectionMatrix[7] * y + projectionMatrix[11] * z + projectionMatrix[15];

    // 2. Check Z condition
    if (clip_z < -1.0) {
        return false;
    }

    // 3. Perspective Divide
    const ndc_x = clip_x / clip_w;
    const ndc_y = clip_y / clip_w;
    
    // 4. Point in Polygon Test (Ray Casting)
    let inside = false;
    const len = polygonVertices.length;
    const limit = len;
    let j = len - 1;

    for (let i = 0; i < limit; i++) {
        const v_i = polygonVertices[i];
        const v_j = polygonVertices[j];
        
        const intersect = ((v_i.y > ndc_y) !== (v_j.y > ndc_y)) &&
            (ndc_x < (v_j.x - v_i.x) * (ndc_y - v_i.y) / (v_j.y - v_i.y) + v_i.x);
        
        if (intersect) inside = !inside;
        j = i;
    }
    return inside;
}

/**
 * Checks if a point is within a unit cube (after transformation).
 * The cube is defined as having its center at (0,0,0) and side length 1 (from -0.5 to 0.5).
 * @param {number[]} matrix - Transformation matrix (World -> Local)
 * @param {Object} point - {x, y, z}
 * @returns {boolean}
 */
export function isPointInUnitCube(matrix, point) {
    const { x, y, z } = point;
    // Apply matrix to point and check abs value < 0.5
    // Local coords check
    const lx = matrix[0] * x + matrix[4] * y + matrix[8] * z + matrix[12];
    const ly = matrix[1] * x + matrix[5] * y + matrix[9] * z + matrix[13];
    const lz = matrix[2] * x + matrix[6] * y + matrix[10] * z + matrix[14];

    return (Math.abs(lx) <= 0.5 && Math.abs(ly) <= 0.5 && Math.abs(lz) <= 0.5);
}

/**
 * Sets vector components from a flat buffer array.
 * @param {Object} vec - Target object {x, y, z}
 * @param {Float32Array|Array} buffer - Source buffer
 * @param {number} offset - Index offset in buffer
 */
export function setVectorFromBuffer(vec, buffer, offset) {
    vec.x = buffer[offset + 0];
    vec.y = buffer[offset + 1];
    vec.z = buffer[offset + 2];
}

/**
 * Checks if a point is within bounds defined by a matrix (e.g., Zoom Box).
 * If boundsMatrix is null/undefined, returns true (no bounds).
 * @param {number[]} boundsMatrix - Inverse World Matrix of the box
 * @param {Object} point - {x, y, z}
 * @returns {boolean}
 */
export function isPointInBounds(boundsMatrix, point) {
    if (!boundsMatrix) return true;
    return isPointInUnitCube(boundsMatrix, point);
}
