import * as THREE from "../../libs/three.js/build/three.module.js";
import {Measure} from "../utils/Measure.js";
import {EventDispatcher} from "../EventDispatcher.js";
import {Utils} from "../utils.js";

export class SegmentLabelingTool extends EventDispatcher {
    constructor(viewer) {
        super();

        this.viewer = viewer;
        this.renderer = viewer.renderer;
        this.scene = new THREE.Scene();
        this.scene.name = 'scene_segment_labeling';
        this.light = new THREE.PointLight(0xffffff, 1.0);
        this.scene.add(this.light);

        this.viewer.inputHandler.registerInteractiveScene(this.scene);

        this.onRemove = (e) => { this.scene.remove(e.measure); };
        this.onAdd = (e) => { this.scene.add(e.measure); };

        this.viewer.addEventListener("update", this.update.bind(this));
        this.viewer.addEventListener("render.pass.perspective_overlay", this.render.bind(this));
    }

    startInsertion(args = {}) {
        let domElement = this.viewer.renderer.domElement;

        let measure = new Measure();

        this.dispatchEvent({
            type: 'start_inserting_label',
            measure: measure
        });

        measure.showDistances = false;
        measure.showArea = false;
        measure.showAngles = false;
        measure.showCoordinates = true;
        measure.showHeight = false;
        measure.maxMarkers = Infinity;
        measure.name = 'Segment Labeling';

        this.scene.add(measure);

        let cancel = {
            callback: null
        };

        let insertionCallback = (e) => {
            if (e.button === THREE.MOUSE.LEFT) {
                measure.addMarker(
                    measure.points[measure.points.length - 1].position.clone()
                );
                
                if (this.viewer.labelingManager && this.viewer.labelingManager.handleSegmentClicks) {
                    this.viewer.labelingManager.handleSegmentClicks(
                        measure.points[measure.points.length - 2]
                    );
                    
                    measure.removeMarker(measure.points.length - 2);
                    
                    this.viewer.inputHandler.startDragging(
                        measure.spheres[measure.spheres.length - 1]
                    );
                }

            } else if (e.button === THREE.MOUSE.RIGHT) {
                cancel.callback();
            }
        };

        cancel.callback = e => {
            domElement.removeEventListener('mouseup', insertionCallback, false);
            this.viewer.scene.removeMeasurement(measure); 
            this.scene.remove(measure);

            if(args.onFinish){
                args.onFinish();
            }
        };

        domElement.addEventListener('mouseup', insertionCallback, false);

        measure.addMarker(new THREE.Vector3(0, 0, 0));
        this.viewer.inputHandler.startDragging(
            measure.spheres[measure.spheres.length - 1]
        );

        return measure;
    }

    update() {
        let camera = this.viewer.scene.getActiveCamera();
        let domElement = this.renderer.domElement;
        
        const renderAreaSize = this.renderer.getSize(new THREE.Vector2());
		let clientWidth = renderAreaSize.width;
		let clientHeight = renderAreaSize.height;

        this.light.position.copy(camera.position);
        
        // Update children (Measures)
        for (let object of this.scene.children) {
             if (object instanceof Measure) {
                 object.update();
                 
                 // Update sphere scale
                 for(let sphere of object.spheres){
                    let distance = camera.position.distanceTo(sphere.getWorldPosition(new THREE.Vector3()));
                    let pr = Utils.projectedRadius(1, camera, distance, clientWidth, clientHeight);
                    let scale = (15 / pr);
                    sphere.scale.set(scale, scale, scale);
                }
             }
        }
    }

    render() {
        this.viewer.renderer.render(this.scene, this.viewer.scene.getActiveCamera());
    }
}
