
import * as THREE from "../../libs/three.js/build/three.module.js";
import {PolygonClipVolume} from "../utils/PolygonClipVolume.js";
import {EventDispatcher} from "../EventDispatcher.js";

export class PolygonLabelingTool extends EventDispatcher {
    constructor(viewer) {
        super();

        this.viewer = viewer;
        this.renderer = viewer.renderer;
        
        this.sceneMarker = new THREE.Scene();
        this.sceneMarker.name = "scene_polygon_labeling";
        
        this.viewer.inputHandler.registerInteractiveScene(this.sceneMarker);

        this.onRemove = (e) => { 
            this.sceneMarker.remove(e.volume); 
        };
        this.onAdd = (e) => { 
            this.sceneMarker.add(e.volume); 
        };

        this.viewer.addEventListener("update", this.update.bind(this));
        this.viewer.addEventListener("render.pass.perspective_overlay", this.render.bind(this));
    }

    startInsertion(args = {}) {
        let type = args.type || null;
        // if (!type) return null; // Logic in LabelingManager ensures type is passed, but snippet has this check.

        let domElement = this.viewer.renderer.domElement;
        let canvasSize = this.viewer.renderer.getSize(new THREE.Vector2());

        // Create SVG with <polygon> instead of polylines
        let svg = $(`
            <svg height="${canvasSize.height}" width="${canvasSize.width}" style="position:absolute; pointer-events: none; top:0; left:0;">
                <defs>
                    <marker id="diamond" markerWidth="12" markerHeight="12" refX="6" refY="6" markerUnits="userSpaceOnUse">
                        <circle cx="6" cy="6" r="4" fill="white" stroke="black" stroke-width="2"/>
                    </marker>
                </defs>

                <polygon fill="rgba(0, 128, 255, 0.3)" stroke="white" stroke-width="2"
                    marker-start="url(#diamond)" 
                    marker-mid="url(#diamond)" 
                    marker-end="url(#diamond)"
                    points=""
                />
            </svg>
            `);
        $(domElement.parentElement).append(svg);

        let polygonClipVolume = new PolygonClipVolume(
            this.viewer.scene.getActiveCamera().clone()
        );

        this.dispatchEvent({ type: "start_inserting_clipping_volume" });

        this.sceneMarker.add(polygonClipVolume);

        let cancel = { callback: null };

        let insertionCallback = (e) => {
            if (e.button === THREE.MOUSE.LEFT) {
                polygonClipVolume.addMarker();

                if (polygonClipVolume.markers.length > 1) {
                    let lastMarker = polygonClipVolume.markers[polygonClipVolume.markers.length - 2];
                    let newMarker = polygonClipVolume.markers[polygonClipVolume.markers.length - 1];
                    newMarker.position.copy(lastMarker.position);
                }
                
                // Add point to <polygon>
                let polygon = svg.find("polygon")[0];
                let newPoint = svg[0].createSVGPoint();
                newPoint.x = e.offsetX;
                newPoint.y = e.offsetY;
                polygon.points.appendItem(newPoint);
                
                // If this is the FIRST point, add a second 'runner' point for visual feedback
                if (polygon.points.numberOfItems === 1) {
                    let runnerPoint = svg[0].createSVGPoint();
                    runnerPoint.x = e.offsetX;
                    runnerPoint.y = e.offsetY;
                    polygon.points.appendItem(runnerPoint);
                }
                
                this.viewer.inputHandler.startDragging(
                    polygonClipVolume.markers[polygonClipVolume.markers.length - 1]
                );
                
                // Trigger as soon as 3 points are selected
                if (polygonClipVolume.markers.length === 3) {
                    if (this.viewer.labelingManager && this.viewer.labelingManager.handlePolygon) {
                        this.viewer.labelingManager.handlePolygon(polygonClipVolume);
                    }
                }
            } else if (e.button === THREE.MOUSE.RIGHT) {
                cancel.callback(e);
            }
        };

        let mouseMoveCallback = (e) => {
            let polygon = svg.find("polygon")[0];
            if (polygon && polygon.points.numberOfItems > 0) {
                let runner = polygon.points.getItem(polygon.points.numberOfItems - 1);
                runner.x = e.offsetX;
                runner.y = e.offsetY;
            }
        };

        cancel.callback = (e) => {
            // Remove SVG
            svg.remove();

            if (polygonClipVolume.markers.length > 3) {
                polygonClipVolume.removeLastMarker();
                polygonClipVolume.initialized = true;
                
                 // Remove from local tool scene as it is handed over or completed
                this.sceneMarker.remove(polygonClipVolume);
                
            } else {
                 // Cancelled before enough points
                 this.sceneMarker.remove(polygonClipVolume);
            }
            
            this.viewer.renderer.domElement.removeEventListener(
                "mouseup",
                insertionCallback,
                false
            );
            this.viewer.renderer.domElement.removeEventListener(
                "mousemove",
                mouseMoveCallback,
                false
            );
            this.viewer.removeEventListener(
                "cancel_insertions",
                cancel.callback
            );
            this.viewer.inputHandler.enabled = true;

            if(args.onFinish){
                args.onFinish();
            }
        };

        this.viewer.addEventListener("cancel_insertions", cancel.callback);
        this.viewer.renderer.domElement.addEventListener(
            "mouseup",
            insertionCallback,
            false
        );
        this.viewer.renderer.domElement.addEventListener(
            "mousemove",
            mouseMoveCallback,
            false
        );
        this.viewer.inputHandler.enabled = false;

        polygonClipVolume.addMarker();
        this.viewer.inputHandler.startDragging(
            polygonClipVolume.markers[polygonClipVolume.markers.length - 1]
        );

        return polygonClipVolume;
    }

    update() {
        
    }

    render() {
        this.viewer.renderer.render(this.sceneMarker, this.viewer.scene.getActiveCamera());
    }
}
