import { isPointInBounds, setVectorFromBuffer, multiplyMatrices } from "../utils/GeometryUtils.js";
import * as THREE from "../../../libs/three.js/build/three.module.js";

export class ClusterSelector {
    /**
     * Finds indices of points that match the cluster criteria and are within the active zoom box.
     * 
     * @param {Object} nodeData - extracted data { position, labels, clusterId, matrixWorld }
     * @param {Object} payload - command payload { attribute, value }
     * @param {Object} activeZoomBox - The active zoom box object (optional)
     * @returns {number[]} Array of point indices
     */
    static select(nodeData, payload, activeZoomBox) {
        const { position, matrixWorld } = nodeData;
        const { attribute, value } = payload;
        const clusterId = nodeData[attribute];
        
        const affectedIndices = [];

        // If filtering by "point source id" or "ClusterID", we check that attribute
        // The payload usually comes as { attribute: 'point source id', value: 123 }
        // We'll trust the caller provided the correct 'clusterId' buffer in nodeData 
        // that corresponds to the 'attribute' in payload, OR check attribute name.
        
        // Note: For now, assuming 'clusterId' passed in nodeData IS the buffer we want to check against 'value'.
        // In LabelingManager/Engine, we must ensure we extract the right attribute.
        
        if (!clusterId) return [];

        // Prepare Zoom Box Matrix (World -> Local)
        let boxInverted = null;
        if (activeZoomBox) {
            // Compute inverse world matrix of the zoom box
            // We need activeZoomBox.matrixWorld inverse * node.matrixWorld -> Point in Box Local Space
            // Actually, usually we test: PointWorld in BoxWorld
            // Box check: isPointInUnitCube( InverseBoxMatrix * PointWorld )
            // PointWorld = NodeMatrix * PointLocal
            // Combined: TestMatrix = InverseBoxMatrix * NodeMatrix
            
            const boxInverse = new THREE.Matrix4().copy(activeZoomBox.matrixWorld).invert();
            const nodeMatrix = new THREE.Matrix4().fromArray(matrixWorld);
            const combined = boxInverse.multiply(nodeMatrix);
            boxInverted = combined.elements;
        }

        const tempVec = { x: 0, y: 0, z: 0 };
        const numPoints = position.length / 3;

        for (let i = 0; i < numPoints; i++) {
            // Check Cluster ID match
            if (clusterId[i] === value) {
                // If Zoom Box is active, check bounds
                if (boxInverted) {
                    setVectorFromBuffer(tempVec, position, i * 3);
                     // Note: setVectorFromBuffer gets local node coordinates.
                     // boxInverted (Combined Matrix) transforms Local Node -> Local Box
                     // isPointInBounds checks if result is in unit cube
                    if (isPointInBounds(boxInverted, tempVec)) {
                        affectedIndices.push(i);
                    }
                } else {
                    affectedIndices.push(i);
                }
            }
        }

        return affectedIndices;
    }
}
