
import * as THREE from "../../libs/three.js/build/three.module.js";
import {Line2} from "../../libs/three.js/lines/Line2.js";
import {LineGeometry} from "../../libs/three.js/lines/LineGeometry.js";
import {LineMaterial} from "../../libs/three.js/lines/LineMaterial.js";
import {Measure} from "../utils/Measure.js";

export class ShapefileLoader{

	constructor(){
		this.transform = null;
	}

	async load(path){

		const matLine = new LineMaterial( {
			color: 0xff0000,
			linewidth: 3, // in pixels
			resolution:  new THREE.Vector2(1000, 1000),
			dashed: false
		} );

		const features = await this.loadShapefileFeatures(path);
		const node = new THREE.Object3D();
		
		for(const feature of features){
			const fnode = this.featureToSceneNode(feature, matLine);
			node.add(fnode);
		}

		let setResolution = (x, y) => {
			matLine.resolution.set(x, y);
		};

		const result = {
			features: features,
			node: node,
			setResolution: setResolution,
		};

		return result;
	}

	featureToSceneNode(feature, matLine){
		let geometry = feature.geometry;
		
		let color = new THREE.Color(1, 1, 1);

		let transform = this.transform;
		if(transform === null){
			transform = {forward: (v) => v};
		}
		
		if(feature.geometry.type === "Point"){
			let sg = new THREE.SphereGeometry(1, 18, 18);
			let sm = new THREE.MeshNormalMaterial();
			let s = new THREE.Mesh(sg, sm);
			
			let [long, lat] = geometry.coordinates;
			let pos = transform.forward([long, lat]);
			
			s.position.set(...pos, 20);
			
			s.scale.set(10, 10, 10);
			
			return s;
		}else if(geometry.type === "LineString"){
			let coordinates = [];
			
			let min = new THREE.Vector3(Infinity, Infinity, Infinity);
			for(let i = 0; i < geometry.coordinates.length; i++){
				let [long, lat] = geometry.coordinates[i];
				let pos = transform.forward([long, lat]);
				
				min.x = Math.min(min.x, pos[0]);
				min.y = Math.min(min.y, pos[1]);
				min.z = Math.min(min.z, 20);
				
				coordinates.push(...pos, 20);
				if(i > 0 && i < geometry.coordinates.length - 1){
					coordinates.push(...pos, 20);
				}
			}
			
			for(let i = 0; i < coordinates.length; i += 3){
				coordinates[i+0] -= min.x;
				coordinates[i+1] -= min.y;
				coordinates[i+2] -= min.z;
			}
			
			const lineGeometry = new LineGeometry();
			lineGeometry.setPositions( coordinates );

			const line = new Line2( lineGeometry, matLine );
			line.computeLineDistances();
			line.scale.set( 1, 1, 1 );
			line.position.copy(min);
			
			return line;
		}else if(geometry.type === "Polygon"){
			for(let pc of geometry.coordinates){
				let coordinates = [];
				
				let min = new THREE.Vector3(Infinity, Infinity, Infinity);
				for(let i = 0; i < pc.length; i++){
					let [long, lat] = pc[i];
					let pos = transform.forward([long, lat]);
					
					min.x = Math.min(min.x, pos[0]);
					min.y = Math.min(min.y, pos[1]);
					min.z = Math.min(min.z, 20);
					
					coordinates.push(...pos, 20);
					if(i > 0 && i < pc.length - 1){
						coordinates.push(...pos, 20);
					}
				}
				
				for(let i = 0; i < coordinates.length; i += 3){
					coordinates[i+0] -= min.x;
					coordinates[i+1] -= min.y;
					coordinates[i+2] -= min.z;
				}

				const lineGeometry = new LineGeometry();
				lineGeometry.setPositions( coordinates );

				const line = new Line2( lineGeometry, matLine );
				line.computeLineDistances();
				line.scale.set( 1, 1, 1 );
				line.position.copy(min);
				
				return line;
			}
		}else{
			console.log("unhandled feature: ", feature);
		}
	}

	async loadShapefileFeatures(file){
		let features = [];

		let source = await shapefile.open(file);

		while(true){
			let result = await source.read();

			if (result.done) {
				break;
			}

			if (result.value && result.value.type === 'Feature' && result.value.geometry !== undefined) {
				features.push(result.value);
			}
		}

		return features;
	}

	static async loadAndIntersect(viewer, file) {
        // file is a File object (blob) from input
        const buffer = await file.arrayBuffer();

        if (typeof shapefile === 'undefined') {
            console.error("shapefile library not found");
            return;
        }

        const source = await shapefile.open(buffer);
        
        // Get scene bounding box
        const box = viewer.scene.getBoundingBox();
        
        // Iterate features
        let result = await source.read();
        while (!result.done) {
            const feature = result.value;
            
            if (feature.geometry.type === 'Polygon') {
                for(const ring of feature.geometry.coordinates){
                     // Clip
                     const clippedPoints = clipPolygonToBox(ring, box);
                     
                     if(clippedPoints.length > 2){
                        // Add measurement
                         ShapefileLoader.addMeasurement(viewer, clippedPoints, feature.properties);
                     }
                }
            } else if(feature.geometry.type === 'MultiPolygon'){
                 for(const polygon of feature.geometry.coordinates){
                     for(const ring of polygon){
                         const clippedPoints = clipPolygonToBox(ring, box);
                         if(clippedPoints.length > 2){
                             ShapefileLoader.addMeasurement(viewer, clippedPoints, feature.properties);
                         }
                     }
                 }
            }
            
            result = await source.read();
        }
    }

    static addMeasurement(viewer, points, properties) {
        const measure = new Measure();
        measure.name = "Imported Polygon";
        if(properties && properties.Name){
            measure.name = properties.Name;
        }

        measure.closed = true;
        measure.showDistances = true;
        measure.showArea = true;
        measure.showEdges = true;

        for (const p of points) {
            const z = viewer.scene.getBoundingBox().min.z + 1; 
            measure.addMarker(new THREE.Vector3(p.x, p.y, z));
        }

        viewer.scene.addMeasurement(measure);
    }

};

// Helper: Point in Box
function isPointInBox(p, box) {
    return p.x >= box.min.x && p.x <= box.max.x &&
           p.y >= box.min.y && p.y <= box.max.y;
}

// Helper: Sutherland-Hodgman Polygon Clipping against a Box (2D XY plane)
function clipPolygonToBox(polygonPoints, box) {
    let outputList = polygonPoints.map(p => new THREE.Vector3(p[0], p[1], 0));

    // AABB Clipping
    const clipAxis = (points, val, isMin, isX) => {
        const newPoints = [];
        if(points.length === 0) return newPoints;
        
        let S = points[points.length - 1];
        
        for(let E of points){
            const sVal = isX ? S.x : S.y;
            const eVal = isX ? E.x : E.y;
            
            const isInside = (pVal) => isMin ? pVal >= val : pVal <= val;
            
            if(isInside(eVal)){
                if(!isInside(sVal)){
                    // Entered
                    const t = (val - sVal) / (eVal - sVal);
                    const interp = new THREE.Vector3().lerpVectors(S, E, t);
                    newPoints.push(interp);
                }
                newPoints.push(E);
            } else if(isInside(sVal)){
                // Exited
                const t = (val - sVal) / (eVal - sVal);
                const interp = new THREE.Vector3().lerpVectors(S, E, t);
                newPoints.push(interp);
            }
            S = E;
        }
        return newPoints;
    }

    outputList = clipAxis(outputList, box.min.x, true, true);  // Min X
    outputList = clipAxis(outputList, box.max.x, false, true); // Max X
    outputList = clipAxis(outputList, box.min.y, true, false); // Min Y
    outputList = clipAxis(outputList, box.max.y, false, false);// Max Y
    
    return outputList;
}

